--
-- Table structure for table `sales_transactions`
--

DROP TABLE IF EXISTS `sales_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `sales_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_number` varchar(255) NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `channel` enum('pos_toko','ecommerce') NOT NULL,
  `payment_method` enum('tunai','cod','transfer_bank','qris') NOT NULL,
  `order_status` enum('menunggu_pembayaran','diproses','dikirim','selesai') NOT NULL DEFAULT 'menunggu_pembayaran',
  `discount_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(14,2) NOT NULL,
  `shipping_address` text DEFAULT NULL,
  `transaction_date` date NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sales_transactions_invoice_number_unique` (`invoice_number`),
  KEY `sales_transactions_user_id_foreign` (`user_id`),
  KEY `sales_transactions_channel_order_status_index` (`channel`,`order_status`),
  KEY `sales_transactions_transaction_date_index` (`transaction_date`),
  CONSTRAINT `sales_transactions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=801 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

